""" Get line and column (1-based) from character index """
def _get_line_col(code: str, idx: int) -> object {
    line = len(code[:(idx + 1)].splitlines());
    col = idx - (code[:(idx + 1)].rfind('\n') + 1);
    return (line, col);
}

"""Given a list of letters, remove any empty strings.
    >>> remove_blanks(['a', '', 'b', '', 'c'])
    ['a', 'b', 'c']
    """
def remove_blanks(letters: list) -> object {
    cleaned = [];
    for letter in letters {
        if (letter != "") {
            cleaned.append(letter);
        }
    }
    return cleaned;
}

