"""
    Utility function to construct a list of command-line arguments in the form that is stored
    in sys.argv. This can then be fed to the main function and used to run CoverView.
    """
def make_command_line_arguments(
    bam_file_name: Any,
    bed_file_name: Any,
    config_file_name: Any,
    transcript_file_name: Any,
    gui_output_file_name: Any
) -> object {
    arguments_list = ["-i", bam_file_name];
    if (bed_file_name is not None) {
        arguments_list.extend(["-b", bed_file_name]);
    }
    if (config_file_name is not None) {
        arguments_list.extend(["-c", config_file_name]);
    }
    if (transcript_file_name is not None) {
        arguments_list.extend(["-t", transcript_file_name]);
    }
    if (gui_output_file_name is not None) {
        arguments_list.extend(["--gui_json_output_file", gui_output_file_name]);
    }
    return arguments_list;
}

"""Computes a contingency table for given predictions.

    :param ys: true labels
    :type ys: iterable
    :param yhats: predicted labels
    :type yhats: iterable
    :param positive: the positive label

    :return: TP, FP, TN, FN

    >>> ys =    [True, True, True, True, True, False]
    >>> yhats = [True, True, False, False, False, True]
    >>> tab = contingency_table(ys, yhats, 1)
    >>> print(tab)
    (2, 1, 0, 3)

    """
def contingency_table(ys: Any, yhats: Any, positive: Any = True) -> object {
    TP = 0;
    TN = 0;
    FP = 0;
    FN = 0;
    for (y, yhat) in zip(ys, yhats) {
        if (y == positive) {
            if (y == yhat) {
                TP += 1;
            } else {
                FN += 1;
            }
        } elif (y == yhat) {
            TN += 1;
        } else {
            FP += 1;
        }
    }
    return (TP, FP, TN, FN);
}

"""Enumerate genes"""
def enumerate_genes(genes: Any) -> object {
    schema = {};
    for (i, x) in enumerate(genes) {
        if (x in schema) {
            schema[x].append(i);
        } else {
            schema[x] = [i];
        }
    }
    return schema;
}

